//! Parser for the `products[]` table of the kernel's
//! `drivers/net/usb/qmi_wwan.c`.
//!
//! The table is a list of C initializers using macros such as
//! `QMI_FIXED_INTF()` or `USB_VENDOR_AND_INTERFACE_INFO()`. Only the macro
//! calls are interpreted; the `.driver_info` assignment is implied by the
//! macro, and the `..._quirk_dtr` variants are the ones carrying the DTR
//! quirk.

use proc_macro2::{Literal, Span, TokenStream};
use quote::quote;
use serde::Serialize;
use syn::LitInt;

/// Header of the generated file.
const BANNER: &str = "//! Generated by `cargo xtask qmi-table`; do not edit.\n//!";

/// One `products[]` entry.
#[derive(Debug, Serialize)]
pub struct Entry {
    /// Section the entry appears under, e.g. `1. CDC ECM like devices`.
    pub section: Option<String>,
    /// `idVendor`, four hex digits.
    pub vendor: u16,
    /// `idProduct`, four hex digits; absent for vendor-wide matches.
    pub product: Option<u16>,
    /// What the entry matches on.
    pub kind: Match,
    /// `QMI_WWAN_QUIRK_DTR`: the firmware ignores QMI requests until DTR is set.
    pub set_dtr: bool,
    /// The kernel comment for the entry.
    pub comment: Option<String>,
}

impl Entry {
    /// The `QmiEntry` this entry turns into, as a token stream.
    fn initializer(&self) -> TokenStream {
        let vendor = hex(self.vendor, 4);
        let product = match self.product {
            Some(product) => {
                let product = hex(product, 4);
                quote! { Some(#product) }
            }
            None => quote! { None },
        };
        let set_dtr = self.set_dtr;

        match self.kind {
            Match::Interface(number) => {
                let number = Literal::u8_unsuffixed(number);
                quote! { QmiEntry::interface(#vendor, #product, #number, #set_dtr), }
            }
            Match::Class {
                class,
                subclass,
                protocol,
            } => {
                let class = hex(class.into(), 2);
                let subclass = hex(subclass.into(), 2);
                let protocol = hex(protocol.into(), 2);
                quote! { QmiEntry::class(#vendor, #product, #class, #subclass, #protocol, #set_dtr), }
            }
        }
    }
}

#[derive(Debug, Serialize)]
pub struct QmiTable {
    /// URL the table was fetched from.
    pub source: String,
    pub entries: Vec<Entry>,
}

#[derive(Debug, Clone, Copy, Serialize)]
pub enum Match {
    Interface(u8),
    Class {
        class: u8,
        subclass: u8,
        protocol: u8,
    },
}

/// Constants used as macro arguments, from `include/linux/usb/*.h`.
const CONSTANTS: &[(&str, u16)] = &[
    ("HUAWEI_VENDOR_ID", 0x12d1),
    ("USB_CLASS_VENDOR_SPEC", 0xff),
    ("USB_SUBCLASS_VENDOR_SPEC", 0xff),
    ("USB_CDC_SUBCLASS_ETHERNET", 0x06),
    ("USB_CDC_PROTO_NONE", 0x00),
    ("USB_CLASS_COMM", 0x02),
];

impl QmiTable {
    /// Parse the whole C source and extract every `products[]` entry.
    pub fn parse(source_url: &str, source: &str) -> Result<Self, String> {
        let lines: Vec<&str> = source.lines().collect();
        let start = lines
            .iter()
            .position(|line| line.contains("products[] = {"))
            .ok_or("`products[]` table not found")?;
        let end = lines[start + 1..]
            .iter()
            .position(|line| line.trim() == "};")
            .map(|offset| start + 1 + offset)
            .ok_or("end of `products[]` table not found")?;

        let mut entries = Vec::new();
        let mut section = None;
        let mut current = String::new();

        for line in &lines[start + 1..end] {
            let line = line.trim();
            if line.is_empty() {
                continue;
            }

            if current.is_empty() {
                if let Some(comment) = whole_line_comment(line) {
                    section = Some(comment);
                    continue;
                }
                if !line.starts_with('{') {
                    continue;
                }
            }

            if !current.is_empty() {
                current.push(' ');
            }
            current.push_str(line);

            // A comment never spans lines inside the table, so the line alone
            // tells us whether the entry is closed.
            let code =
                strip_comment(line).trim_end_matches(|c: char| c == ',' || c.is_whitespace());
            if code.ends_with('}') {
                if let Some(entry) = parse_entry(&current, section.clone())? {
                    entries.push(entry);
                }
                current.clear();
            }
        }

        if !current.is_empty() {
            return Err(format!("unterminated entry: {current}"));
        }

        Ok(Self {
            source: source_url.to_owned(),
            entries,
        })
    }

    /// Render the table as the `qmi_device` module `rm-qmi` compiles in.
    ///
    /// The output is a plain `const` table so the filters it drives can be
    /// computed at compile time. The initializers are built as token streams;
    /// only the section and entry comments are written as text, since tokens
    /// carry no comments.
    pub fn to_rust(&self) -> String {
        let mut out = String::from(BANNER);
        out.push_str(&format!("\n//! Source: {}\n\n", self.source));
        out.push_str("use crate::QmiEntry;\n\n");
        out.push_str(&format!(
            "/// Number of `products[]` entries.\npub const COUNT: usize = {};\n\n",
            self.entries.len() + LOCAL_ENTRIES.len()
        ));
        out.push_str(
            "/// `products[]` entries of the kernel's QMI WWAN driver.\n\
             pub const ENTRIES: [QmiEntry; COUNT] = [\n",
        );

        let mut section: Option<&str> = None;
        for entry in &self.entries {
            if entry.section.as_deref() != section {
                section = entry.section.as_deref();
                if let Some(section) = section {
                    out.push_str(&format!("    // {section}\n"));
                }
            }

            out.push_str("    ");
            out.push_str(&entry.initializer().to_string());

            if let Some(comment) = &entry.comment {
                out.push_str(&format!(" // {comment}"));
            }
            out.push('\n');
        }

        if !LOCAL_ENTRIES.is_empty() {
            out.push_str("\n    // Local additions, kept across regeneration\n");
            for entry in LOCAL_ENTRIES {
                out.push_str("    ");
                out.push_str(entry);
                out.push('\n');
            }
        }

        out.push_str("];\n");
        out
    }
}

/// Entries the kernel table does not carry but this workspace needs. Kept here
/// so that `cargo xtask qmi-table` does not drop them.
const LOCAL_ENTRIES: &[&str] = &[
    // The EM05-CE exposes QMI as a vendor interface once `AT+QCFG="usbnet",0`
    // selects the RmNet composition; upstream's table has no 2c7c:0127 entry.
    "QmiEntry::class(0x2c7c, Some(0x0127), 0xff, 0xff, 0xff, true), // Quectel EM05-CE (local entry)",
];

/// A zero padded hexadecimal literal, like the driver's own constants.
fn hex(value: u16, digits: usize) -> LitInt {
    LitInt::new(
        &format!("0x{value:0width$x}", width = digits),
        Span::call_site(),
    )
}

fn parse_entry(text: &str, section: Option<String>) -> Result<Option<Entry>, String> {
    let comment = text.find("/*").and_then(|start| {
        let rest = &text[start + 2..];
        rest.find("*/").map(|end| rest[..end].trim().to_owned())
    });

    if comment
        .as_deref()
        .is_some_and(|comment| comment.contains("END"))
    {
        return Ok(None);
    }

    let (vendor, product, kind, set_dtr) = if let Some(args) = macro_args(text, "QMI_QUIRK_SET_DTR")
    {
        (
            id(&args, 0)?,
            Some(id(&args, 1)?),
            Match::Interface(number(&args, 2)?),
            true,
        )
    } else if let Some(args) = macro_args(text, "QMI_FIXED_INTF") {
        (
            id(&args, 0)?,
            Some(id(&args, 1)?),
            Match::Interface(number(&args, 2)?),
            false,
        )
    } else if let Some(args) = macro_args(text, "QMI_GOBI1K_DEVICE") {
        (
            id(&args, 0)?,
            Some(id(&args, 1)?),
            Match::Interface(3),
            false,
        )
    } else if let Some(args) = macro_args(text, "QMI_GOBI_DEVICE") {
        (
            id(&args, 0)?,
            Some(id(&args, 1)?),
            Match::Interface(0),
            false,
        )
    } else if let Some(args) = macro_args(text, "QMI_MATCH_FF_FF_FF") {
        (
            id(&args, 0)?,
            Some(id(&args, 1)?),
            Match::Class {
                class: 0xff,
                subclass: 0xff,
                protocol: 0xff,
            },
            // The macro pairs the match with `qmi_wwan_info_quirk_dtr`.
            true,
        )
    } else if let Some(args) = macro_args(text, "USB_VENDOR_AND_INTERFACE_INFO") {
        (id(&args, 0)?, None, class(&args, 1)?, false)
    } else if let Some(args) = macro_args(text, "USB_DEVICE_AND_INTERFACE_INFO") {
        (id(&args, 0)?, Some(id(&args, 1)?), class(&args, 2)?, false)
    } else {
        return Err(format!("no known macro in entry: {text}"));
    };

    Ok(Some(Entry {
        section,
        vendor,
        product,
        kind,
        set_dtr,
        comment,
    }))
}

/// The comma separated arguments of `name(...)`, if the call is present.
fn macro_args<'a>(text: &'a str, name: &str) -> Option<Vec<&'a str>> {
    let rest = &text[text.find(name)? + name.len()..];
    let rest = rest.trim_start().strip_prefix('(')?;
    // No macro argument contains parentheses.
    let end = rest.find(')')?;
    Some(rest[..end].split(',').map(str::trim).collect())
}

fn id(args: &[&str], index: usize) -> Result<u16, String> {
    let token = args
        .get(index)
        .ok_or_else(|| format!("missing argument {index}"))?;
    parse_number(token)
}

fn number(args: &[&str], index: usize) -> Result<u8, String> {
    let token = args
        .get(index)
        .ok_or_else(|| format!("missing argument {index}"))?;
    u8::try_from(parse_number(token)?).map_err(|_| format!("`{token}` does not fit in a byte"))
}

/// `class, subclass, protocol` starting at `index`.
fn class(args: &[&str], index: usize) -> Result<Match, String> {
    Ok(Match::Class {
        class: number(args, index)?,
        subclass: number(args, index + 1)?,
        protocol: number(args, index + 2)?,
    })
}

fn parse_number(token: &str) -> Result<u16, String> {
    if let Some(hex) = token
        .strip_prefix("0x")
        .or_else(|| token.strip_prefix("0X"))
    {
        u16::from_str_radix(hex, 16).map_err(|_| format!("invalid number `{token}`"))
    } else if let Some((_, value)) = CONSTANTS.iter().find(|(name, _)| *name == token) {
        Ok(*value)
    } else {
        token
            .parse()
            .map_err(|_| format!("unknown constant `{token}`"))
    }
}

fn whole_line_comment(line: &str) -> Option<String> {
    let text = line.strip_prefix("/*")?.strip_suffix("*/")?;
    Some(text.trim().to_owned())
}

fn strip_comment(line: &str) -> &str {
    match line.find("/*") {
        Some(start) => &line[..start],
        None => line,
    }
}
